insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8ce90839-46ac-4c09-88d3-7e5231bbade8', 'ja', '彼女の腕に、かっこいいデザインのタトゥーを見つけます。好奇心が伝わるひと言は、どれですか？', '["「そのタトゥー、どんな由来があるんですか？すごくかっこいいですね」", "「そのタトゥー、セクシーで似合っていますね」", "「かっこいいスタイルですね」", "「ほかにもタトゥーがあるんですか？」"]'::jsonb, '彼女の経験への好奇心は、下心なしに、本物のつながりを招きます。')
