insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94a93921-8975-4a5a-ac8a-918d2cfeb071', 'ja', 'なぜ、好奇心を持って声をかけるべきなのですか？', '["惹かれていることを隠せるから", "断られるのを防げるから", "心理的なトリックのように働くから", "プレッシャーを下げ、彼女に「自分は面白い存在だ」と感じさせるから"]'::jsonb, '人は、品定めされたり追いかけられたりするのではなく、ちゃんと見てもらえていると感じたときに、心を開きます。')
