insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95d93e33-2d1c-431f-a2f0-0ed76d7c559c', 'ja', 'ジムで声をかけます。彼女は温かく応じ、そのあとイヤホンをつけ直します。', '["受け入れのサイン。しっかり答えてくれたのは、関わっている証拠", "礼儀のサイン。礼儀として答えたが、続ける気はない", "冷たいサイン。すぐに立ち去れという、失礼な態度"]'::jsonb, '彼女はこちらを認めたうえで、境界線を引きました。引き延ばさずに、引きましょう。')
