insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('96cd2c07-1109-4ded-b869-cec66cf863b9', 'ja', 'バーでストレートに声をかけます。彼女の友人がやって来て、彼女は体を少しそちらへ向けます。', '["何も変えずに話し続ける", "注意を引こうと張り合う", "体の向きが変わったことを指摘する", "友人にも声をかけるか、すっきりと切り上げる"]'::jsonb, '相手の反応を見て合わせるとは、変わっていく状況に合わせることです。')
