insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97f948e5-43c9-49fb-91ea-249d0532afa8', 'ja', 'パーティーで、彼女が飲み物のそばに立っています。一番合うストレートなひと言は、どれですか？', '["「部屋の向こうからお見かけして、どうしてもお話ししたくて来ました」", "「この音楽、大きいですよね？」", "「お手洗いがどこか、ご存じですか？」", "「ここにはよく来るんですか？」"]'::jsonb, '関心をはっきり伝えることは、交流の場という状況に自然に合います。')
