insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a58e14a-b997-4eae-a453-494d620dffc6', 'ja', 'バーで、「どう見ても、最後にみんなをちゃんと家に帰す、しっかり者の役ですよね」と言います。何がうまくいっていますか？', '["具体的な推測なので、彼女はすぐに答えて関わらずにはいられなかった", "自分についてどうしてその結論になったのか、彼女が気になっている", "上の両方"]'::jsonb, '具体的な推測は、反応せずにはいられなくし、すぐに相手を引き込みます。')
