insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9c7e0b10-8bac-4319-8672-b7ce62646374', 'ja', '混み合ったバーで、彼女の隣に立っています。さりげないひと言になるのは、どれですか？', '["この店はいつもこんなに混んでいるのかを聞く", "何を注文するのかを聞く", "魅力的だと伝える", "LINEを聞く"]'::jsonb, '周りの環境についてのひと言は、割り込みではなく、その場に加わるように感じられます。')
