insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fb3d329-54bd-4b72-a37a-6435bb2ff6a4', 'ja', '飲み物が出てくるまで時間がかかることについて、ひと言かけます。彼女はほほえんで、熱心に同意します。', '["いら立って愚痴を言っているだけで、関心があるとは限らない", "自分の不満に同意するかどうか、こちらを試している", "同じだけのエネルギーを返し、関わり続けている"]'::jsonb, '熱のこもった反応と、その話題を続けることは、関わっている証拠です。')
